function pdfBlob(id){
  const bin = atob(PDFS[id].data);
  const bytes = new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++) bytes[i]=bin.charCodeAt(i);
  return new Blob([bytes],{type:'application/pdf'});
}
function descargarPDF(id){
  const a=document.createElement('a');
  a.href=URL.createObjectURL(pdfBlob(id)); a.download=PDFS[id].nombre; a.click();
  toast('Formulario descargado');
}
function abrirPDF(id){ window.open(URL.createObjectURL(pdfBlob(id)),'_blank'); }

