/* ================= COMPONENTE DE CARGA DE DOCUMENTOS ================= */
/* Genérico: lista de docs [nombre,req,multiple,maxMB], almacén de archivos, id contenedor, prefijo callbacks */
function pintarDoclist(contId, docs, store, fnName){
  $(contId).innerHTML = docs.map(([doc,req,multi,maxMB],i)=>{
    const files = store[i]||[];
    return `<div class="doc ${files.length?'ok':''}">
      <div class="info"><b>${doc}${req?' *':''}</b>
        <span>${req?'Obligatorio':'Opcional'}${multi?' · varios archivos':''} · PDF, JPG o PNG · máx. ${maxMB} MB c/u</span>
        ${files.map(f=>`
    <span class="archivo">
        ✓ ${f.name} (${(f.size/1024/1024).toFixed(1)} MB)
    </span>
`).join('')}
      </div>
      <div class="botones">
        <label class="btn btn-ghost btn-sm" style="margin:0">📁 ${files.length&&!multi?'Reemplazar':'Cargar'}
          <input type="file" ${multi?'multiple':''} accept=".pdf,.jpg,.jpeg,.png" onchange="${fnName}(${i},this,${maxMB},${multi})"></label>
        <label class="btn btn-ghost btn-sm" style="margin:0">📷 Tomar foto
          <input type="file" accept="image/*" capture="environment" onchange="${fnName}(${i},this,${maxMB},${multi})"></label>
      </div>
    </div>`;
  }).join('');
}

function cargarGenerico(
    store,
    i,
    input,
    maxMB,
    multi,
    repintar
){

    const nuevos = [];

    for(const f of input.files){

        if(
            f.size >
            maxMB * 1024 * 1024
        ){
            toast(
                `"${f.name}" supera ${maxMB} MB.`
            );
            continue;

        }

        if(
            !/\.(pdf|jpe?g|png)$/i.test(f.name) &&
            !f.type.startsWith("image/")
        ){
            toast(
                "Formato no permitido."
            );
            continue;
        }
        nuevos.push(f);

    }

    if(!nuevos.length){
        input.value = "";
        return;
    }

    console.log("Antes de guardar:", store);

    console.log("Nuevos:", nuevos);

    store[i] = multi
        ? [
            ...(store[i] || []),
            ...nuevos
        ]
        : [
            nuevos[0]
        ];
    input.value = "";
    repintar();

    console.log("Después de guardar:", store);
}


function reservarConsecutivo(){

    if(consecutivoReservado)
        return consecutivoReservado;

    const hoy = new Date();

    const yy =
        String(hoy.getFullYear()).slice(-2);

    const inicio =
        new Date(
            hoy.getFullYear(),
            0,
            0
        );

    const juliano =
        String(
            Math.floor(
                (hoy - inicio) / 86400000
            )
        ).padStart(3,"0");

    const clave =
        `SGP-${yy}${juliano}`;

    const datos =
        JSON.parse(
            localStorage.getItem(
                "sgp_consecutivos"
            ) || "{}"
        );

    if(!datos[clave])
        datos[clave] = 0;

    datos[clave]++;

    consecutivoReservado =
        datos[clave];

    localStorage.setItem(
        "sgp_consecutivos",
        JSON.stringify(datos)
    );

    console.log(
        "================================="
    );

    console.log(
        "CONSECUTIVO RESERVADO"
    );

    console.log(
        "Clave del día:",
        clave
    );

    console.log(
        "Número:",
        consecutivoReservado
    );

    console.log(
        "================================="
    );

    return consecutivoReservado;

}

