function ajustarPorPerfil(){
  const p = wizard.perfil;
  $('w-intro').textContent = 'Tiempo estimado: 3–5 minutos. ' + (p==='hospital'
    ? 'Tenga a mano la documentación clínica y de facturación del paciente.'
    : 'Tenga a mano su cédula y los documentos del evento.');
  $('aviso-perfil').innerHTML = p==='hospital'
    ? '🏥 Presenta: <b>Hospital / Clínica</b>. Complete los datos del <b>paciente asegurado</b> y de su institución.'
    : (p==='corredor' ? '🤝 Presenta: <b>Corredor de seguros</b>. Complete los datos del <b>asegurado</b>.'
    : '🙋 Presenta: <b>Asegurado / Titular</b>. Complete sus datos tal como aparecen en la póliza.');
  $('campo-hospital').classList.toggle('hidden', p!=='hospital');
  const cp=$('campo-proveedor'); if(cp) cp.classList.toggle('hidden', p!=='hospital');
  $('campo-corredora').classList.toggle('hidden', p!=='corredor');
  $('lbl-email').textContent = p==='hospital' ? 'Correo de contacto (facturación)' : 'Correo electrónico';
  // Paso evento: monto según perfil
  const esHosp = p==='hospital';
  $('lbl-monto').textContent = esHosp ? 'Monto facturado (USD)' : 'Monto presentado (USD)';
  $('lbl-monto').classList.toggle('req', esHosp);
  $('chk-monto-wrap').classList.toggle('hidden', esHosp);
  $('ayuda-monto').textContent = esHosp
    ? 'Total facturado de la atención según los documentos adjuntos.'
    : 'Ingrese el total de facturas/gastos de esta atención. Si no lo conoce, el especialista de indemnizaciones lo determinará según sus facturas y las condiciones de la póliza.';
  if(esHosp){ $('f-sinmonto').checked=false; $('f-monto').disabled=false; }
  pintarDocs();
}
