function selServicio(codigo){

    console.log("Servicio:", codigo);

    wizard.servicio = codigo;

    document
        .querySelectorAll(".servicio-card")
        .forEach(card => card.classList.remove("sel"));

    const radio = document.querySelector(
        `input[name="servicio"][value="${codigo}"]`
    );

    if(radio){

        radio.checked = true;

        radio.closest(".servicio-card")
             .classList.add("sel");
    }

    const err = document.getElementById("err-servicio");

    if(err)
        err.style.display = "none";

}


