// Funcion fundido de codigo <<--</gishikoDev_>-->>
function obtenerCodigoReclamo(){

    const hoy = new Date();

    const yy = String(
        hoy.getFullYear()
    ).slice(-2);

    const inicio = new Date(
        hoy.getFullYear(),
        0,
        0
    );

    const juliano = String(
        Math.floor(
            (hoy - inicio) / 86400000
        )
    ).padStart(3,"0");

    return `SGP-${
        yy
    }${
        juliano
    }-${
        String(consecutivoReservado)
            .padStart(4,"0")
    }-${
        wizard.servicio
    }`;

}

function obtenerResumenReclamo(){

    return {

        codigo: obtenerCodigoReclamo(),

        perfil: PERFILES.find(
            p => p.id === wizard.perfil
        )?.nombre || "",

        linea: lineaNombre(wizard.tipo),

        producto: $('f-producto').value,

        servicio:{
            M:"Servicio Médico",
            D:"Servicio Dental",
            V:"Servicio Óptico"
        }[wizard.servicio],

        nombre:$('f-nombre').value,

        cedula:$('f-cedula').value,

        telefono:$('f-tel').value,

        email:$('f-email').value,

        fechaEvento:$('f-fecha').value,

        monto:
            wizard.perfil !== "hospital" &&
            (
                $('f-sinmonto').checked ||
                !$('f-monto').value
            )
            ? "Por determinar"
            : money($('f-monto').value || 0),

        proveedor:$('f-proveedor').value,

        descripcion:$('f-desc').value,

        fechaRecepcion:new Date().toLocaleString("es-PA")

    };

}

function obtenerFechaHora(){

    const ahora = new Date();

    return ahora.toLocaleString(
        "es-PA",
        {
            year:"numeric",
            month:"2-digit",
            day:"2-digit",
            hour:"2-digit",
            minute:"2-digit"
        }
    );

}

