function pintarResumen(){

    const r = obtenerResumenReclamo();

    const nDocs =
    Object.values(documentosReclamo)
        .reduce(
            (s,a)=>s+a.length,
            0
        );

    $('resumen').innerHTML = `

        <dt>Presentado por</dt>
        <dd>
            ${r.perfil}
            ${
                wizard.perfil==="hospital"
                    ? " · "+$('f-hospital').value
                    : ""
            }
            ${
                wizard.perfil==="corredor" &&
                $('f-corredora').value
                    ? " · "+$('f-corredora').value
                    : ""
            }
        </dd>

        <dt>Código de Reclamo</dt>
        <dd>${r.codigo}</dd>

        <dt>Línea</dt>
        <dd>${r.linea}</dd>

        <dt>Producto</dt>
        <dd>${r.producto}</dd>

        <dt>Servicio</dt>
        <dd>${r.servicio}</dd>

        <dt>Asegurado</dt>
        <dd>${r.nombre}</dd>

        <dt>Cédula</dt>
        <dd>${r.cedula}</dd>

        <dt>Correo</dt>
        <dd>${r.email}</dd>

        <dt>Teléfono</dt>
        <dd>${r.telefono}</dd>

        <dt>Fecha del evento</dt>
        <dd>${r.fechaEvento}</dd>

        <dt>Monto reclamado</dt>
        <dd>${r.monto}</dd>

        ${
            r.proveedor
                ? `
                <dt>Proveedor</dt>
                <dd>${r.proveedor}</dd>
                `
                : ""
        }

        <dt>Descripción</dt>
        <dd>${r.descripcion}</dd>

        <dt>Documentos cargados</dt>
        <dd>${nDocs} archivo(s)</dd>

    `;

}

