async function pasoWizard(dir){

    const p = wizard.paso;

    if(dir>0 && !validarPaso(p))
        return;
    if(
        dir>0 &&
        p===1 &&
        !consecutivoReservado
    ){
        reservarConsecutivo();
        console.log(
            "Consecutivo reservado:",
            consecutivoReservado
        );
    }
    if(dir>0 && p===5){
        enviarReclamo();
        return;
    }
    wizard.paso = Math.max(
        0,
        Math.min(5,p+dir)
    );
    refrescarWizard();

setTimeout(() => {

    window.scrollTo({

        top: 0,

        behavior: "smooth"

    });

}, 50);

}

function refrescarWizard(){
  document.querySelectorAll('.wstep').forEach(w=>w.classList.toggle('hidden', Number(w.dataset.paso)!==wizard.paso));
  document.querySelectorAll('#stepper .st').forEach((s,i)=>{
    s.classList.toggle('hecho', i<wizard.paso);
    s.classList.toggle('actual', i===wizard.paso);
  });
  $('btn-atras').style.visibility = wizard.paso===0?'hidden':'visible';
  $('btn-sig').textContent = wizard.paso===5 ? 'Enviar reclamo ✓' : 'Continuar →';
  if(wizard.paso===5) pintarResumen();
}

function cargarDocW(i,input,maxMB,multi){

    cargarGenerico(

        documentosReclamo,

        i,

        input,

        maxMB,

        multi,

        ()=>{

            wizard.archivos = documentosReclamo;

            $("err-docs").style.display = "none";

            pintarDocs();

        }

    );

}

window.cargarDocW = cargarDocW;

