async function enviarReclamo(){

    console.log("[FIREFOX TEST] enviarReclamo() INICIO");

    console.clear();

    console.log("===================================");
    console.log("INICIANDO ENVÍO DEL RECLAMO");
    console.log("===================================");

    mostrarProgresoEnvio();

    let nuevoReclamo = null;
    let reclamoCreado = false;

    try{

        actualizarProgresoEnvio(
            10,
            "Preparando los datos del reclamo..."
        );

        let codigo =
            obtenerCodigoReclamo();

        console.log(
            "Código inicial:",
            codigo
        );

        // ==========================================
        // CONSTRUCCIÓN DEL RECLAMO
        // ==========================================

        const reclamo = {

            num: codigo,

            linea:
                wizard.tipo,

            servicio:
                wizard.servicio,

            producto:
                $('f-producto').value,

            nombre:
                $('f-nombre').value.trim(),

            cedula:
                $('f-cedula').value.trim(),

            email:
                $('f-email').value.trim(),

            tel:
                $('f-tel').value.trim(),

            poliza:
                $('f-poliza')?.value.trim() || "",

            perfil_presenta:
                wizard.perfil,

            hospital:
                wizard.perfil === "hospital"
                    ? $('f-hospital').value.trim()
                    : null,

            corredora:
                wizard.perfil === "corredor"
                    ? $('f-corredora')?.value.trim() || null
                    : null,

            origen:
                "Portal Web",

            fecha_evento:
                $('f-fecha').value,

            monto:
                $('f-sinmonto')?.checked
                    ? null
                    : (
                        $('f-monto').value
                            ? Number(
                                $('f-monto').value
                            )
                            : null
                    ),

            proveedor:
                $('f-proveedor').value.trim(),

            descripcion:
                $('f-desc').value.trim(),

            estado:
                "Recibido",

            docs_count:
                0,

            creado_por:
                "Portal"

        };

        console.log(
            "RECLAMO A INSERTAR"
        );

        console.log(
            reclamo
        );


        // ==========================================
        // PASO 1
        // CREAR RECLAMO
        // ==========================================

        actualizarProgresoEnvio(
            20,
            "Registrando su reclamo..."
        );

        console.log(
            "1. Creando reclamo..."
        );


        /*
         * Intentamos crear el reclamo.
         *
         * Si existe una colisión de consecutivo,
         * generamos automáticamente el siguiente
         * número y volvemos a intentar.
         */

        const MAX_REINTENTOS = 100;

        for(
            let intento = 1;
            intento <= MAX_REINTENTOS;
            intento++
        ){

            try{

                console.log(
                    "-----------------------------------"
                );

                console.log(
                    "INTENTO DE INSERT:",
                    intento
                );

                console.log(
                    "Código:",
                    reclamo.num
                );

                nuevoReclamo =
                    await ReclamosRepository.crear(
                        reclamo
                    );

                reclamoCreado = true;

                console.log(
                    "[FIREFOX TEST] CREAR OK"
                );

                console.log(
                    "Reclamo creado:",
                    nuevoReclamo
                );

                break;

            }
            catch(error){

                console.error(
                    "ERROR CREANDO RECLAMO"
                );

                console.error(
                    error
                );

                console.error(
                    "Código que produjo el error:",
                    reclamo.num
                );


                // ==================================
                // COLISIÓN DE CONSECUTIVO
                // ==================================

                const esColision =
                    error?.code === "23505" &&
                    (
                        error?.message || ""
                    ).includes(
                        "reclamos_num_key"
                    );

                if(!esColision){

                    console.error(
                        "El error NO corresponde a una colisión."
                    );

                    throw error;

                }


                console.warn(
                    "⚠️ COLISIÓN DE CONSECUTIVO"
                );

                console.warn(
                    "El código",
                    reclamo.num,
                    "ya existe."
                );


                if(
                    intento >= MAX_REINTENTOS
                ){

                    console.error(
                        "Se agotaron los reintentos."
                    );

                    throw error;

                }


                actualizarProgresoEnvio(
                    22 + (intento * 2),
                    "Ajustando el número de reclamo..."
                );


                /*
                 * Generamos automáticamente
                 * el siguiente consecutivo.
                 */

                siguienteConsecutivo();


                /*
                 * MUY IMPORTANTE:
                 *
                 * Actualizamos el objeto que será
                 * enviado al INSERT.
                 */

                codigo =
                    obtenerCodigoReclamo();

                reclamo.num =
                    codigo;


                console.log(
                    "Nuevo código para retry:",
                    codigo
                );


                /*
                 * Pequeña pausa para permitir que
                 * Firefox/Android/iOS actualicen
                 * visualmente el progress.
                 */

                await new Promise(
                    resolve =>
                        requestAnimationFrame(
                            resolve
                        )
                );

            }

        }


        if(!reclamoCreado){

            throw new Error(
                "No fue posible crear el reclamo."
            );

        }


        console.log(
            "OK 1"
        );

        console.log(
            nuevoReclamo
        );


        // ==========================================
        // PASO 2
        // DOCUMENTOS
        // ==========================================

        actualizarProgresoEnvio(
            40,
            "Cargando los documentos..."
        );

        console.log(
            "2. Subiendo documentos..."
        );

        const cantidadDocumentos =
            await subirDocumentosReclamo(
                nuevoReclamo.id
            );

        console.log(
            "[FIREFOX TEST] DOCUMENTOS OK"
        );

        console.log(
            "OK 2"
        );

        console.log(
            "Documentos:",
            cantidadDocumentos
        );


        // ==========================================
        // PASO 3
        // VERIFICACIÓN
        // ==========================================

        actualizarProgresoEnvio(
            65,
            "Verificando la información registrada..."
        );

        console.log(
            "3. Verificando reclamo..."
        );


        await new Promise(
            resolve =>
                requestAnimationFrame(
                    resolve
                )
        );


        const verificacion =
            await ReclamosRepository.buscar(
                codigo
            );

        console.log(
            "[FIREFOX TEST] BUSQUEDA OK"
        );

        console.log(
            "OK 3"
        );

        console.log(
            verificacion
        );


        // ==========================================
        // VERIFICACIÓN FALLIDA
        // ==========================================

        if(!verificacion){

            console.error(
                "No fue posible verificar el reclamo."
            );

            actualizarProgresoEnvio(
                100,
                "No fue posible verificar la solicitud."
            );

            setTimeout(
                ocultarProgresoEnvio,
                800
            );

            toast(
                "No fue posible verificar el reclamo."
            );

            return;

        }


        if(
            verificacion.num !== codigo
        ){

            console.error(
                "La verificación del reclamo falló."
            );

            actualizarProgresoEnvio(
                100,
                "La verificación no pudo completarse."
            );

            setTimeout(
                ocultarProgresoEnvio,
                800
            );

            toast(
                "La verificación del reclamo falló."
            );

            return;

        }


        // ==========================================
        // PASO 4
        // CONFIRMACIÓN
        // ==========================================

        actualizarProgresoEnvio(
            82,
            "Confirmando la recepción..."
        );

        console.log(
            "4. Pintando código..."
        );


        /*
         * Aquí utilizamos `codigo`, que ya contiene
         * el nuevo consecutivo en caso de collision.
         */

        $('radicado-num')
            .textContent =
            codigo;


        console.log(
            "Código final:",
            codigo
        );

        console.log(
            "OK 4"
        );


        // ==========================================
        // PASO 5
        // PANTALLA FINAL
        // ==========================================

        actualizarProgresoEnvio(
            95,
            "Preparando la confirmación..."
        );

        console.log(
            "5. Cambiando a pantalla de éxito..."
        );


        document
            .querySelectorAll(".wstep")
            .forEach(w=>{

                w.classList.toggle(
                    "hidden",
                    w.dataset.paso !== "6"
                );

            });


        console.log(
            "OK 5"
        );


        // ==========================================
        // STEPPER
        // ==========================================

        console.log(
            "6. Pintando stepper..."
        );

        document
            .querySelectorAll(
                "#stepper .st"
            )
            .forEach(s=>{

                s.classList.add(
                    "hecho"
                );

                s.classList.remove(
                    "actual"
                );

            });


        console.log(
            "OK 6"
        );


        // ==========================================
        // NAVEGACIÓN
        // ==========================================

        console.log(
            "7. Ocultando navegación..."
        );

        $('nav-wizard')
            .classList.add(
                "hidden"
            );


        console.log(
            "OK 7"
        );


        // ==========================================
        // COMPLETADO
        // ==========================================

        actualizarProgresoEnvio(
            100,
            "¡Reclamo enviado correctamente!"
        );


        console.log(
            "8. Flujo completado."
        );


        await new Promise(
            resolve =>
                setTimeout(
                    resolve,
                    700
                )
        );


        ocultarProgresoEnvio();


        toast(
            "Reclamo " +
            codigo +
            " enviado con éxito"
        );


        console.log(
            "==================================="
        );

        console.log(
            "FLUJO TERMINADO CORRECTAMENTE"
        );

        console.log(
            "Código final:",
            codigo
        );

        console.log(
            "==================================="
        );

    }
    catch(error){

        console.log(
            "==================================="
        );

        console.log(
            "ERROR EN EL FLUJO"
        );

        console.log(
            "==================================="
        );

        console.error(
            error
        );

        console.error(
            error?.stack
        );


        actualizarProgresoEnvio(
            100,
            "No fue posible completar el envío."
        );


        setTimeout(
            ocultarProgresoEnvio,
            900
        );


        toast(
            "No fue posible enviar el reclamo."
        );

    }


    console.log(
        "[FIREFOX TEST] FIN REAL DE enviarReclamo()"
    );

}


