function mostrarProgresoEnvio(){

    const modal =
        $('envio-progress');

    if(!modal)
        return;

    modal.classList.remove('hidden');

    actualizarProgresoEnvio(
        5,
        "Preparando su solicitud..."
    );

}

function actualizarProgresoEnvio(
    porcentaje,
    mensaje
){

    const barra =
        $('envio-progress-bar');

    const texto =
        $('envio-progress-message');

    const porcentajeTexto =
        $('envio-progress-percent');

    if(barra){

        barra.style.width =
            `${porcentaje}%`;

    }

    if(texto){

        texto.textContent =
            mensaje;

    }

    if(porcentajeTexto){

        porcentajeTexto.textContent =
            `${porcentaje}%`;

    }

}

function ocultarProgresoEnvio(){

    const modal =
        $('envio-progress');

    if(!modal)
        return;

    modal.classList.add('hidden');

}





/* ================= PRE-AUTORIZACIÓN ================= */
function cargarDocPA(i,input,maxMB,multi){
  cargarGenerico(paArchivos, i, input, maxMB, multi, ()=>pintarDoclist('pa-docs', DOCS_PA, paArchivos, 'cargarDocPA'));
}
function enviarPreauth(){
  let ok=true;
  ok = marca('pa-asegurado', $('pa-asegurado').value.trim().length>2) && ok;
  ok = marca('pa-cedula', $('pa-cedula').value.trim().length>3) && ok;
  ok = marca('pa-paciente', $('pa-paciente').value.trim().length>2) && ok;
  ok = marca('pa-email', /.+@.+\..+/.test($('pa-email').value)) && ok;
  ok = marca('pa-tel', $('pa-tel').value.trim().length>5) && ok;
  ok = marca('pa-tipo', $('pa-tipo').value!=='') && ok;
  ok = marca('pa-medico', $('pa-medico').value.trim().length>2) && ok;
  ok = marca('pa-desc', $('pa-desc').value.trim().length>10) && ok;
  const faltan = DOCS_PA.some(([_,req],i)=> req && !(paArchivos[i]||[]).length);
  if(faltan){ toast('Cargue los tres documentos requeridos de la solicitud.'); return; }
  if(!$('pa-consent').checked){ toast('Debe autorizar el tratamiento de datos para enviar.'); return; }
  if(!ok){ toast('Revise los campos marcados en rojo.'); return; }
  seqPA++;
  const num = 'PA-2026-' + String(seqPA).padStart(3,'0');
  preauths.unshift({num, asegurado:$('pa-asegurado').value.trim(), cedula:$('pa-cedula').value.trim(), email:$('pa-email').value.trim(), tipo:$('pa-tipo').value, urgente:$('pa-urgente').checked, estado:'Recibida', recibido:hoy.toISOString().slice(0,10), bit:[['Recibida',hoy.toISOString().slice(0,10)]]});
  $('pa-form').classList.add('hidden');
  $('pa-ok').classList.remove('hidden');
  $('pa-num').textContent = num;
  toast('Pre-autorización ' + num + ($('pa-urgente').checked?' (URGENTE)':'') + ' enviada');
}

/* ================= TRACKING (reclamos + pre-autorizaciones) ================= */
function buscarTracking(){
  const num = $('t-num').value.trim().toUpperCase();
  const id = $('t-id').value.trim().toLowerCase();
  let r=null, esPA=false;
  if(num.startsWith('PA-')){
    r = preauths.find(x=>x.num===num && (x.cedula.toLowerCase()===id || x.email.toLowerCase()===id));
    esPA=true;
  } else {
    r = reclamos.find(x=>x.num===num && (x.cedula.toLowerCase()===id || x.email.toLowerCase()===id));
  }
  $('t-error').style.display = r?'none':'block';
  $('t-resultado').classList.toggle('hidden', !r);
  if(!r) return;
  $('t-estado').textContent = r.estado;
  $('t-estado').className = 'badge ' + (BADGE[r.estado]||'b-gris');
  if(esPA){
    $('t-cabecera').innerHTML = `<b style="color:var(--profundo)">${r.num}</b> · Pre-autorización · ${r.tipo}<br><span style="color:var(--pizarra);font-size:13px">Asegurado ${r.asegurado} · Recibida el ${r.recibido}</span>`;
    const flujo = ['Recibida','En evaluación', r.estado==='Negada'?'Negada':'Autorizada'];
    const idx = flujo.indexOf(r.estado);
    const notas = {'Recibida':'Su solicitud fue radicada en el portal.','En evaluación':'Nuestros médicos asesores están evaluando la solicitud.','Autorizada':'Autorización emitida. Válida por 30 días.','Negada':'Revise el correo con el detalle de la decisión.'};
    $('t-timeline').innerHTML = flujo.map((e,i)=>{
      const ev = r.bit.find(b=>b[0]===e);
      return `<div class="tl-item ${i<idx?'hecho':(i===idx?'actual':'')}"><b>${e}</b><span>${ev?ev[1]+' · ':''}${notas[e]}</span></div>`;
    }).join('');
    return;
  }
  $('t-cabecera').innerHTML = `<b style="color:var(--profundo)">${r.num}</b> · ${lineaNombre(r.linea)} · ${r.producto} · ${r.nombre}<br><span style="color:var(--pizarra);font-size:13px">Recibido el ${r.recibido}${r.monto?' · Monto reclamado '+money(r.monto):''}</span>`;
  const notas = {'Recibido':'Su reclamo fue radicado y está en verificación de documentos.','En Proceso':'Registrado en nuestro sistema; el especialista analiza el reclamo según las condiciones de su póliza.','Pendiente de Información':'Necesitamos documentos o información adicional. Revise el correo con el detalle.','Pagado':'El pago fue procesado. Verá el detalle de la liquidación en su correo.','Rechazado':'El reclamo no procedió. Revise el correo con la explicación y sus opciones.'};
  let flujo;
  if(r.estado==='Rechazado') flujo=['Recibido','En Proceso','Rechazado'];
  else if(r.estado==='Pendiente de Información') flujo=['Recibido','Pendiente de Información','En Proceso','Pagado'];
  else flujo=['Recibido','En Proceso','Pagado'];
  const idx = flujo.indexOf(r.estado);
  $('t-timeline').innerHTML = flujo.map((e,i)=>{
    const ev = r.bit.find(b=>b[0]===e);
    const cls = i<idx?'hecho':(i===idx?(e==='Pendiente de Información'?'alerta':'actual'):'');
    return `<div class="tl-item ${cls}"><b>${e}</b><span>${ev?ev[1]+' · ':''}${notas[e]}</span></div>`;
  }).join('');
}

