// Tipos de accidente para AP
SC.TIPOS_ACC = [
  {id:'transito', nombre:'Tránsito', req:['reporte_policial']},
  {id:'laboral', nombre:'Laboral', req:['reporte_css']},
  {id:'escolar', nombre:'Escolar', req:['reporte_escuela']},
  {id:'hogar', nombre:'Hogar', req:[]},
  {id:'deportivo', nombre:'Deportivo', req:[]},
  {id:'muerte', nombre:'Muerte accidental', req:['cert_defuncion']},
  {id:'otro', nombre:'Otro', req:[]}
];

// Documentos AP según sub-producto y tipo
SC.docsAP = function(subproducto, tipoAcc){
  const escolar = /Escolar/i.test(subproducto||'');
  const base = escolar
    ? [['Formulario firmado',1,0,10],['Certificado médico',1,0,10],['Reporte del accidente firmado y sellado por la escuela',1,0,10],['Cédula del representante',1,0,10]]
    : [['Formulario firmado',1,0,10],['Certificado médico',1,0,10],['Reporte del accidente',1,0,10],['Cédula del solicitante',1,0,10]];
  const opt = [['Facturas de gastos médicos',0,1,20],['Recetas médicas',0,1,20],['Resultados de exámenes',0,1,20],['Fotos del evento',0,1,20]];
  if(tipoAcc==='transito') base.push(['Reporte policial',1,1,20]);
  if(tipoAcc==='laboral') base.push(['Reporte CSS',1,1,20]);
  if(tipoAcc==='muerte'){ base.push(['Certificado de defunción',1,0,10]); opt.push(['Autopsia (si aplica)',0,0,20]); }
  if(!escolar) opt.push(['Incapacidad médica (si aplica)',0,0,10]);
  return base.concat(opt);
};

// Documentos Vida (fallecimiento)
SC.docsVida = function(){
  return [
    ['Formulario de reclamación de beneficiarios (firmado)',1,0,10],
    ['Certificado de defunción',1,0,10],
    ['Cédula del asegurado fallecido (copia)',1,0,10],
    ['Cédula de los beneficiarios',1,1,10],
    ['Historia clínica / informe forense',0,1,20],
    ['Certificado del médico tratante',0,0,10]
  ];
};

// Inyectar campos condicionales de AP y VD en el paso Evento
SC.inyectarCamposEvento = function(){
  // v5: mostrar/ocultar campos base según producto
  const _campoFecha = document.getElementById('f-fecha')?.closest('.campo');
  const _campoMonto = document.getElementById('campo-monto');
  const _campoProv  = document.getElementById('campo-proveedor');
  const _campoDesc  = document.getElementById('f-desc')?.closest('.campo');
  const _tipo = wizard.tipo;
  const _hideForVida = (_tipo === 'VD');
  [_campoFecha,_campoMonto,_campoProv,_campoDesc].forEach(el=>{
    if(!el) return;
    el.classList.toggle('hidden', _hideForVida);
  });
  // Para Salud y AP volvemos a mostrarlos por si venían ocultos
  if(_tipo === 'AP' && _campoProv){ _campoProv.classList.remove('hidden'); }
  
  const contEv = document.querySelector('#w-paso-3, [data-paso="evento"]') || $('f-fecha')?.closest('.grid') || $('f-fecha')?.parentElement?.parentElement;
  if(!contEv) return;
  let extra = document.getElementById('extra-evento');
  if(!extra){
    extra = document.createElement('div');
    extra.id = 'extra-evento';
    extra.className = 'grid';
    extra.style.marginTop = '10px';
    contEv.parentNode.insertBefore(extra, contEv.nextSibling);
  }
  const tipo = wizard.tipo;
  extra.innerHTML = '';
  if(tipo === 'AP'){
    const sub = ($('f-producto')?.value)||'';
    extra.innerHTML = `
      <div class="campo"><label class="req">Tipo de accidente</label>
        <select id="ap-tipo" onchange="SC.actualizarDocsDinamicos()">
          <option value="">Seleccione…</option>
          ${SC.TIPOS_ACC.map(t=>`<option value="${t.id}">${t.nombre}</option>`).join('')}
        </select>
        <p class="ayuda">${/Escolar/i.test(sub)?'Recuerde: en AP Escolar el reporte debe venir firmado y sellado por la escuela.':'Seleccione el tipo para ajustar los documentos requeridos.'}</p>
      </div>
      <div class="campo"><label>Hora aproximada</label><input id="ap-hora" type="time"></div>
      <div class="campo"><label>Lugar del evento</label><input id="ap-lugar" placeholder="Ciudad, calle, referencia"></div>`;
  } else if(tipo === 'VD'){
    extra.innerHTML = `
      <div class="campo"><label class="req">Fecha de fallecimiento</label><input id="vd-fecha" type="date"></div>
      <div class="campo"><label class="req">Causa (según certificado)</label><input id="vd-causa" placeholder="Ej. Natural, accidente, en investigación"></div>
      <div class="campo"><label class="req">Nombre del beneficiario reclamante</label><input id="vd-benef" placeholder="Nombre completo"></div>
      <div class="campo"><label class="req">Parentesco con el asegurado</label><select id="vd-parent"><option value="">Seleccione…</option><option>Cónyuge</option><option>Hijo(a)</option><option>Padre/Madre</option><option>Otro</option></select></div>`;
    // En Vida no re-preguntamos datos del asegurado: sólo el reclamante/beneficiario.
    // Ocultamos el campo "Descripción del evento" si existe y agregamos ayuda.
  }
  SC.actualizarDocsDinamicos();
};

SC.actualizarDocsDinamicos = function(){
  if(!wizard.tipo || !wizard.perfil) return;
  let docs;
  if(wizard.tipo === 'AP'){
    const sub = ($('f-producto')?.value)||'';
    const tipoAcc = ($('ap-tipo')?.value)||'';
    docs = SC.docsAP(sub, tipoAcc);
  } else if(wizard.tipo === 'VD'){
    docs = SC.docsVida();
  } else {
    docs = DOCS[wizard.tipo][wizard.perfil];
  }
  wizard._docsActivos = docs;
  pintarDoclist('doclist', docs, wizard.archivos, 'cargarDocW');
};

